{
  "name": "sdio_tx_desc_replenish",
  "confidence": "medium",
  "docstring": "Processes RX IRQ state and then replenishes the SDIO host-to-device TX descriptor ring by allocating, linking, and posting descriptors until the queue reaches its configured target depth, writing the doorbell.",
  "subsystem": "ipc",
  "var_renames": {
    "a1": "host_txq_ops",
    "a2": "txq_state",
    "v21": "target_depth",
    "v6": "current_count",
    "v9": "buf_idx",
    "v11": "new_desc",
    "v12": "buf_base"
  },
  "struct_hints": [
    {
      "offset": 4,
      "meaning": "host_txq_ops context pointer passed to allocator/release callbacks"
    },
    {
      "offset": 8,
      "meaning": "host_txq_ops virtual/operation table pointer"
    },
    {
      "offset": 4,
      "meaning": "txq_state tail descriptor pointer"
    },
    {
      "offset": 12,
      "meaning": "txq_state current descriptor count (uint16)"
    },
    {
      "offset": 0,
      "meaning": "descriptor buffer address field"
    },
    {
      "offset": 4,
      "meaning": "descriptor next descriptor pointer field"
    },
    {
      "offset": 8,
      "meaning": "descriptor control or length field zero-initialized on allocation"
    }
  ]
}
